import 'dart:convert';

import 'package:camereon/core/photo/android_photo_saver.dart';
import 'package:camereon/core/photo/photo_images.dart';
import 'package:camereon/core/photo/photo_saver.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  testWidgets('Android MediaStore saves a fully redacted JPEG', (tester) async {
    // Synthetic 48x32 black JPEG. No original photograph or personal data.
    final jpeg = RedactedJpeg(
      bytes: base64Decode(
        '',
      ),
      width: 48,
      height: 32,
    );
    expect(await AndroidPhotoSaver().save(jpeg), isA<SaveSucceeded>());
  });

  testWidgets('native saver rejects non-JPEG bytes', (tester) async {
    const channel = MethodChannel('dev.camereon/photo_saver');
    expect(
      await channel.invokeMethod<String>('save', {
        'bytes': Uint8List.fromList([1, 2, 3]),
      }),
      'failed',
    );
  });
}
